={{ (() => {
  const row = $json;
  const cfg = $('Checkout Defaults').first().json;

  // per-row value if present, otherwise the workflow default
  const pick = (rowVal, fallback) => {
    const v = String(rowVal ?? '').trim();
    return v === '' ? fallback : v;
  };
  const bool = (rowVal, fallback) => {
    const v = String(rowVal ?? '').trim().toLowerCase();
    if (v === '') return fallback;
    return ['true','si','sí','yes','1','x'].includes(v);
  };

  const days = Number(pick(row['Checkout expiry days'], cfg.expiryDays));
  const methods = pick(row['Checkout methods'], cfg.paymentMethods)
                    .split(',').map(s => s.trim()).filter(Boolean);

  return JSON.stringify({
    amount: Math.round(Number(row['Total Invoice (incluing VAT) ']) * 100),
    currency: pick(row['Checkout currency'], cfg.currency),
    billing: { address: { country: pick(row['Checkout country'], cfg.country) } },

    processing_channel_id: pick(row['Checkout channel'], cfg.processingChannelId),

    reference: row.importKey,
    description: row['Invoice description'],
    metadata: { importKey: row.importKey, contactName: row['*ContactName'] },

    expires_in: days * 86400,
    locale: pick(row['Checkout locale'], cfg.locale),
    return_url: pick(row['Checkout return url'], cfg.returnUrl),

    allow_payment_methods: methods,
    '3ds': { enabled: bool(row['Checkout 3DS'], cfg.threeDs), attempt_n3d: true },
    capture: bool(row['Checkout capture'], cfg.capture),

    customer: { name: row['*ContactName'], email: row['Customer email'] },
    payment_method_configuration: { card: { store_payment_details: 'disabled' } }
  });
})() }}

